#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define STACK_MAX 64

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("ERROR");
        return 0;
    }
    long stack[STACK_MAX];
    int top = 0;
    for (int i = 1; i < argc; ++i) {
        char *tok = argv[i];
        if (strlen(tok) == 1) {
            char op = tok[0];
            if (op == '+' || op == '-' || op == '*' || op == '/') {
                if (top < 2) { puts("ERROR"); return 0; }
                long b = stack[--top];
                long a = stack[--top];
                long res = 0;
                switch (op) {
                    case '+': res = a + b; break;
                    case '-': res = a - b; break;
                    case '*': res = a * b; break;
                    case '/': if (b == 0) { puts("ERROR"); return 0; } res = a / b; break;
                }
                if (top >= STACK_MAX) { puts("ERROR"); return 0; }
                stack[top++] = res;
                continue;
            }
        }
        char *endptr;
        long val = strtol(tok, &endptr, 10);
        if (endptr == tok || *endptr != '\0') { puts("ERROR"); return 0; }
        if (top >= STACK_MAX) { puts("ERROR"); return 0; }
        stack[top++] = val;
    }
    if (top != 1) { puts("ERROR"); return 0; }
    printf("%ld\n", stack[0]);
    return 0;
}
